use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet},io::Read,process::Command,fmt::Write};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_dir(){walk(&p,out)}else if e.file_type().unwrap().is_file(){out.push(p)}}}
fn main(){let r=Path::new("/tmp/zopro-grouping-lower-bound");let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-grouping-lower-bound");let dest=report.join("artifacts");fs::create_dir_all(&dest).unwrap();let a=read(r.join("analysis.json"));assert_eq!(a["sdk_requests"],2988);assert_eq!(a["distinct_gnark_exports"],102);assert!(!a["adoption_gate_passed"].as_bool().unwrap(),"passing candidate requires production adoption before this rejection closeout");
 for(p,h)in read(r.join("perf-plan.json"))["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");let edit=read(r.join("edits.json"));for(rel,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(rel)),h.as_str().unwrap());let p=r.join("candidate").join(rel);if rel==edit["path"].as_str().unwrap(){let s=fs::read_to_string(p).unwrap();let appended=edit["appended"].as_str().unwrap();let s=s.strip_suffix(appended).unwrap();let new=edit["new"].as_str().unwrap();assert_eq!(s.matches(new).count(),1);let old=s.replacen(new,edit["old"].as_str().unwrap(),1);assert_eq!(format!("{:x}",Sha256::digest(old.as_bytes())),h.as_str().unwrap());assert_eq!(hash(r.join("grouping.original.rs")),h.as_str().unwrap());}else{assert_eq!(hash(p),h.as_str().unwrap());}}
 assert_eq!(hash("/tmp/zopro-grouping-module/native/candidate-sdk"),"03e1260e89068c2bec37a2471c34e93628a9f081903e1b7eee9cab9c306aaf3d");let inv=read(r.join("proof-inventory.json"));assert_eq!(inv.as_object().unwrap().len(),204);let mut identities=BTreeSet::new();for(p,h)in inv.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){assert_eq!(fs::metadata(p).unwrap().len(),164);assert!(identities.insert(h.as_str().unwrap()));}}assert_eq!(identities.len(),102);
 let close=json!({"status":"closed verified; adoption gate failed","sdk_requests":2988,"distinct_gnark_exports":102,"proof_public_members":204,"profile_samples":a["profile_samples"],"lost_records":0,"native_core_tests":113,"new_core_tests":4,"raw_tests":2,"cubic_tests":6,"eligible_bitmap_bytes_at_most":65536,"bitmap_fits_existing_phase_forecast":true,"accepted_170_sources_and_SDK_unchanged":true,"all_originals_recoverable":true,"adopted":false,"goal_achieved":false,"new_cloud_resources":false,"next_prior_proof_count":5340,"no_successful_capture_repeated":true});fs::write(r.join("closeout.json"),serde_json::to_vec_pretty(&close).unwrap()).unwrap();
 let mut text=String::from("# Exact cardinality lower bound before scalar grouping\n\nThe bitmap candidate does not pass the declared local adoption gate. Accepted production is unchanged. It replaces some rejected full grouping passes with an exact occupied-bit lower bound; it changes no proving math or grouping cutoff. This is a local Ryzen9950X comparison, with no new AWS or Aeglos execution.\n\n## Verified SDK latency\n\nThree rotated/reversed fresh-process blocks,31timed requests after three primes,32Rayon workers pinned to CPUs0–31. OFF and ON use the same executable and differ only in the new feature's explicit runtime flag. Witness solving, fresh randomness, proving, SDK verification and serialization are included. Loading/preparation is excluded. Each cell is the median of the three process medians.\n\n| Circuit | Accepted ms | OFF ms | ON ms | ON/OFF paired geometric mean | ON maximum RSS MiB | Supplied M5 CPU / Metal ms | Candidate CPU / Metal speedup |\n|---|---:|---:|---:|---:|---:|---:|---:|\n");
 for name in ["1x2-w32","2x2-w32","4x2-w32","8x2-w32","12x2-w32","16x2-w32","24x2-w32","merge-24x1-w32","merge-54x1-w32"]{let c=&a["cases"][name];let latency=&c["latency"];let reference=if c["M5"].is_object(){format!("{:.0} / {:.0}",c["M5"]["supplied_cpu_ms"].as_f64().unwrap(),c["M5"]["supplied_metal_ms"].as_f64().unwrap())}else{"not supplied".into()};let speed=if c["M5"].is_object(){format!("{:.2}× / {:.2}×",c["M5"]["candidate_CPU_speedup"].as_f64().unwrap(),c["M5"]["candidate_Metal_speedup"].as_f64().unwrap())}else{"—".into()};writeln!(text,"|{}|{:.6}|{:.6}|{:.6}|{:.6}|{:.2}|{}|{}|",name.trim_end_matches("-w32"),latency["accepted"]["request_ms"].as_f64().unwrap(),latency["off"]["request_ms"].as_f64().unwrap(),latency["on"]["request_ms"].as_f64().unwrap(),c["on_off_geomean"].as_f64().unwrap(),latency["on"]["whole_process_maxrss_mib"].as_f64().unwrap(),reference,speed).unwrap();}
 writeln!(text,"\nPrimary paired ON/OFF={:.6}, winning {} of3blocks. Original-eight aggregate ON/OFF={:.6}; ON/accepted={:.6}. RSS is the maximum whole SDK process, including loading/setup/primes; it is not incremental scratch or minimum RAM. M5 references are historical supplied values. No shape is established at10× CPU speedup by this experiment.\n\n## Gate outcome\n",a["primary_on_off_geomean"].as_f64().unwrap(),a["primary_block_wins"],a["original_eight_on_off_geomean"].as_f64().unwrap(),a["original_eight_on_accepted_geomean"].as_f64().unwrap()).unwrap();
 text.push_str("The [predeclared gate](artifacts/design.md) requires primary ON/OFF≤0.98 with at least two block wins, no other shape slower than1.02, original-eight aggregate ON/OFF and ON/accepted≤0.995, and OFF/accepted calibration within1.03 paired and1.05 per block. All results are retained. Calibration failures and regressions:\n\n");for field in ["calibration_failures","regressions"]{let failures=a[field].as_array().unwrap();if failures.is_empty(){writeln!(text,"- {field}: none.").unwrap();}else{for f in failures{writeln!(text,"- {}",f.as_str().unwrap()).unwrap();}}}
 text.push_str("\n## Algorithm and memory\n\nThe [preceding stage diagnostic](../2026-10-26-stage-costs/README.md) measured a1.35ms local primary G2 grouping policy, including a1.10ms serial map build/free which ultimately declines. That evidence motivates this separate test; it does not guarantee equal SDK latency savings when arithmetic competes for the same workers.\n\nFor8192≤n<32768 and the existing80percent grouping cutoff, hash nonzero scalars into next_power_of_two(16*n) bits. The number of occupied bits cannot exceed distinct nonzero scalars. If it exceeds floor(n*80/100), the unchanged exact grouping policy would necessarily reject. Otherwise run the original exact policy. Collisions only cause fallback. This is neither a probabilistic rejection decision nor a changed cutoff. It does not repeat the earlier95percent grouping-acceptance experiment.\n\nThe bitmap is temporary,16–64KiB, allocated after the existing checked grouping reservation and freed before full map/values/counts/classes allocation. Its vector allocation plus the existing64byte allowance fits within the already forecast classes Vec<u32> phase for every eligible size. Larger queries and other cutoffs allocate nothing extra. There is no retained key lookup table and no universal memory-cap change.\n\n## Qualification and CPU profiles\n\nAll113 unfiltered native core tests pass, including four new tests covering exact cutoffs/zeros, adversarial collisions, independent cardinality oracles and every eligible size's memory bound. The generated-IFMA check, two raw tests and six cubic tests pass. Field source is unchanged; existing field qualification is inherited. All-nine OFF/ON correctness preflights complete72SDK18Gnark. The81timing processes complete2754SDK81Gnark, followed by three primary199Hz cycle profiles completing162SDK3Gnark. Total **2988SDK calls,102distinct independently Gnark-verified exports and204proof/public members**. Fixture public hashes,164byte proof lengths, source/binary pins and distinct randomized proof identities are checked against5238 prior exports. No successful capture is repeated.\n\nProfiles follow all latencies and never decide adoption. Sample shares are aggregate user cycles, not wall-time savings. The generic grouping classifier matches scalar_groups/hashbrown. Compiler inlining can attribute grouping to a caller category, and a separately emitted new lower_bound symbol may fall into other. These categories are not isolated grouping-stage costs and should not be compared as such. Raw decoded symbols are retained, so no missing symbol is treated as zero work.\n\n| Variant | Profile samples | Lost records | Grouping category % | Epoch + scheduler % |\n|---|---:|---:|---:|---:|\n");
 for mode in ["accepted","off","on"]{let p=&a["profiles"][mode];let category=&p["category_percent"];writeln!(text,"|{mode}|{}|{}|{:.3}|{:.3}|",p["samples"],p["lost_records"],category["grouping"].as_f64().unwrap_or(0.),category["epoch"].as_f64().unwrap_or(0.)+category["scheduler"].as_f64().unwrap_or(0.)).unwrap();}
 text.push_str("\nAll170 accepted source files and the accepted SDK are unchanged. The candidate is preserved privately and is not adopted. No phone, TEE, memory-pressure, giant-circuit, concurrent throughput or C7a qualification is added. The original all-eight10× CPU objective remains unmet.\n\n[Full analysis](artifacts/analysis.json), [frozen measurement configuration](artifacts/perf-plan.json), [exact source change](artifacts/edits.json), [new module](artifacts/candidate/crates/zopro-core/src/msm_affine/grouping/lower_bound.rs), [native validation](artifacts/native/result.json), [raw timing/profile rows](artifacts/performance/rows.json), [proof inventory](artifacts/proof-inventory.json) and [artifact index](artifacts/artifact-index.json) retain the evidence. Raw perf.data and binaries remain local with hashes; decoded profiles and proof exports are archived.\n");fs::write(report.join("README.md"),text).unwrap();
 let mut files=Vec::new();for d in ["native","preflight","preflight-proofs","performance"]{walk(&r.join(d),&mut files);}for e in fs::read_dir(r).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_file(){files.push(e.path());}}for rel in ["crates/zopro-core/src/msm_affine/grouping.rs","crates/zopro-core/src/msm_affine/grouping/lower_bound.rs","crates/zopro-bench/examples/cpu-sdk.rs","crates/zopro-bench/examples/support/perf.rs"]{files.push(r.join("candidate").join(rel));}files.sort();files.dedup();let mut index=BTreeMap::new();let mut raw=BTreeMap::new();for p in files{let rel=p.strip_prefix(r).unwrap();if p.file_name().unwrap()=="perf.data"{let o=Command::new("sudo").args(["-n","sha256sum"]).arg(&p).output().unwrap();assert!(o.status.success());raw.insert(rel.display().to_string(),String::from_utf8(o.stdout).unwrap().split_whitespace().next().unwrap().to_owned());continue;}let ext=p.extension().and_then(|x|x.to_str()).unwrap_or("");if !matches!(ext,"rs"|"json"|"md"|"log"|"txt"|"proof"|"public"){continue;}let target=dest.join(rel);fs::create_dir_all(target.parent().unwrap()).unwrap();fs::copy(&p,&target).unwrap();index.insert(rel.display().to_string(),hash(target));}fs::copy("/tmp/zopro-grouping-module/production-source-manifest.json",dest.join("accepted-source-manifest.json")).unwrap();index.insert("accepted-source-manifest.json".into(),hash(dest.join("accepted-source-manifest.json")));for(p,h)in &index{assert_eq!(hash(dest.join(p)),*h);}fs::write(dest.join("artifact-index.json"),serde_json::to_vec_pretty(&json!({"sha256":index,"raw_profiles_local_only":raw,"binaries_local_only":true})).unwrap()).unwrap();println!("Closed2988SDK102Gnark; {} archive hashes; rawprofiles{}",index.len(),raw.len());}
